CREATE OR REPLACE FUNCTION public.fabricar_empleado(p_emp text, p_items jsonb, p_lote jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  res jsonb;
begin
  if not hg_permitido() then raise exception 'SIN_CUENTA'; end if;
  if coalesce(p_emp, '') = '' or p_lote->>'id' is null or p_lote->>'empId' is distinct from p_emp then
    raise exception 'FAB_DATOS';
  end if;
  perform pg_advisory_xact_lock(hashtext('hg-fab-' || p_emp));
  if hg_pendientes_empleado(p_emp) > 0 then
    raise exception 'FAB_BLOQUEADA';
  end if;
  res := mover_stock(p_items);
  insert into datos (clave, valor, actualizado) values ('fablote:' || (p_lote->>'id'), p_lote, now());
  insert into datos (clave, valor, actualizado)
    values ('rev', jsonb_build_object('n', (extract(epoch from now()) * 1000)::bigint::text || '-fab'), now())
    on conflict (clave) do update set valor = excluded.valor, actualizado = excluded.actualizado;
  return res;
end $function$

CREATE OR REPLACE FUNCTION public.hacer_copia(p_tipo text DEFAULT 'diaria'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id  text;
  v_dat jsonb;
  v_stk jsonb;
  v_cnt integer;
  v_n   integer;
  v_dia date;
begin
  if not hg_permitido() then raise exception 'SIN_CUENTA'; end if;
  if p_tipo not in ('diaria', 'antes-restaurar') then raise exception 'COPIA_TIPO'; end if;
  v_dia := (now() at time zone 'Europe/Madrid')::date;
  v_id := case when p_tipo = 'diaria' then 'diaria-' || extract(isodow from v_dia)::int else 'antes-restaurar' end;
  if p_tipo = 'diaria' and exists (select 1 from copias where id = v_id and (creada at time zone 'Europe/Madrid')::date = v_dia) then
    return jsonb_build_object('id', v_id, 'hecha', false);
  end if;
  select coalesce(jsonb_object_agg(clave, jsonb_build_object('v', valor, 'a', actualizado)), '{}'::jsonb), count(*)
    into v_dat, v_n from datos where not hg_fuera_de_copia(clave);
  select coalesce(jsonb_object_agg(producto, to_jsonb(s) - 'producto'), '{}'::jsonb) into v_stk from stock s;
  select valor into v_cnt from contador where id = 1;
  insert into copias (id, tipo, creada, datos, stock, contador, filas, bytes)
    values (v_id, p_tipo, now(), v_dat, v_stk, v_cnt, v_n, pg_column_size(v_dat) + pg_column_size(v_stk))
    on conflict (id) do update set creada = excluded.creada, datos = excluded.datos, stock = excluded.stock,
      contador = excluded.contador, filas = excluded.filas, bytes = excluded.bytes;
  return jsonb_build_object('id', v_id, 'hecha', true, 'filas', v_n);
end $function$

CREATE OR REPLACE FUNCTION public.hg_alta_empleado(p_nombre text, p_puesto text, p_tel text, p_discord text, p_por text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  arr jsonb; e jsonb; ex jsonb; v_id text; hoy date := (now() at time zone 'Europe/Madrid')::date; ms bigint := (extract(epoch from now())*1000)::bigint;
  sueldo int := case p_puesto when 'Aprendiz de armero' then 2000 when 'Armero' then 2500 when 'Armero experto' then 3000 when 'Gerente' then 4000 else 2000 end;
begin
  if coalesce(trim(p_nombre),'') = '' then raise exception 'NOMBRE'; end if;
  select valor into arr from datos where clave = 'empleados' for update;
  if arr is null or jsonb_typeof(arr) <> 'array' then arr := '[]'::jsonb; end if;
  select x into ex from jsonb_array_elements(arr) x where lower(trim(x->>'name')) = lower(trim(p_nombre)) or (p_discord <> '' and x->>'discord' = p_discord) limit 1;
  if ex is not null then
    -- ya estaba en la web: solo se enlaza con su usuario de Discord
    update datos set valor = (select jsonb_agg(case when x->>'id' = ex->>'id' then x || jsonb_build_object('discord', p_discord, 'telegrama', coalesce(nullif(x->>'telegrama',''), p_tel)) else x end) from jsonb_array_elements(arr) x), actualizado = now() where clave = 'empleados';
    return jsonb_build_object('id', ex->>'id', 'existia', true, 'nombre', ex->>'name', 'puesto', ex->>'puesto');
  end if;
  v_id := 'e' || to_hex(ms) || substr(md5(random()::text), 1, 3);
  e := jsonb_build_object('id', v_id, 'alta', ms, 'name', trim(p_nombre), 'puesto', p_puesto, 'sueldo', sueldo, 'horas', 10,
         'inicio', to_char(hoy, 'YYYY-MM-DD'), 'prueba', to_char(hoy + 6, 'YYYY-MM-DD'), 'telegrama', p_tel, 'discord', p_discord, 'origen', 'discord', 'contratoPend', true);
  update datos set valor = arr || jsonb_build_array(e), actualizado = now() where clave = 'empleados';
  insert into datos (clave, valor, actualizado) values ('log:' || v_id || 'L',
    jsonb_build_object('id', v_id || 'L', 'ts', ms, 'who', coalesce(nullif(p_por,''), 'Dirección'), 'cat', 'Personal', 'lines', jsonb_build_array('Alta desde Discord: ' || trim(p_nombre) || ' como ' || p_puesto || ' (telegrama ' || coalesce(p_tel,'—') || ')')), now());
  return jsonb_build_object('id', v_id, 'existia', false, 'nombre', trim(p_nombre), 'puesto', p_puesto);
end $function$

CREATE OR REPLACE FUNCTION public.hg_ascenso_empleado(p_id text, p_por text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  arr jsonb; ex jsonb; nx text; ns int; ms bigint := (extract(epoch from now())*1000)::bigint;
  hoy int := ((now() at time zone 'Europe/Madrid')::date - date '1970-01-01');
begin
  select valor into arr from datos where clave = 'empleados' for update;
  select x into ex from jsonb_array_elements(coalesce(arr,'[]')) x where x->>'id' = p_id limit 1;
  if ex is null then raise exception 'NO_EXISTE'; end if;
  nx := case ex->>'puesto' when 'Aprendiz de armero' then 'Armero' when 'Armero' then 'Armero experto' when 'Armero experto' then 'Gerente' end;
  if nx is null then raise exception 'SIN_ASCENSO'; end if;
  if coalesce((ex->>'sueldo')::numeric,0) <= 0 or coalesce(ex->>'inicio','') = '' then raise exception 'SIN_CONTRATO'; end if;
  ns := case nx when 'Armero' then 2500 when 'Armero experto' then 3000 when 'Gerente' then 4000 end;
  update datos set valor = (select jsonb_agg(case when x->>'id' = p_id then
      x || jsonb_build_object('puesto', nx, 'sueldo', ns, 'prueba', '', 'sinPrueba', true, 'alta', ms, 'contratoPend', 'ascenso',
        'ascensos', coalesce(x->'ascensos','[]'::jsonb) || jsonb_build_array(jsonb_build_object('ts', ms, 'desde', hoy + 1, 'de', ex->>'puesto', 'a', nx, 'antes', (ex->>'sueldo')::numeric, 'nuevo', ns)))
      else x end) from jsonb_array_elements(arr) x), actualizado = now()
    where clave = 'empleados';
  insert into datos (clave, valor, actualizado) values ('log:a' || to_hex(ms) || p_id,
    jsonb_build_object('id', 'a' || to_hex(ms) || p_id, 'ts', ms, 'who', coalesce(nullif(p_por,''), 'Dirección'), 'cat', 'Personal',
      'lines', jsonb_build_array('Ascenso desde Discord: ' || (ex->>'name') || ' · ' || (ex->>'puesto') || ' → ' || nx)), now());
  return jsonb_build_object('id', p_id, 'nombre', ex->>'name', 'de', ex->>'puesto', 'a', nx, 'antes', (ex->>'sueldo')::numeric, 'nuevo', ns, 'discord', ex->>'discord');
end $function$

CREATE OR REPLACE FUNCTION public.hg_baja_empleado(p_discord text, p_por text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare arr jsonb; ex jsonb; ms bigint := (extract(epoch from now())*1000)::bigint;
begin
  if coalesce(p_discord,'') = '' then raise exception 'DISCORD'; end if;
  select valor into arr from datos where clave = 'empleados' for update;
  select x into ex from jsonb_array_elements(coalesce(arr,'[]')) x where x->>'discord' = p_discord limit 1;
  if ex is null then return jsonb_build_object('estaba', false); end if;
  if ex->>'puesto' = 'Jefe' then raise exception 'JEFE'; end if;
  update datos set valor = coalesce((select jsonb_agg(x) from jsonb_array_elements(arr) x where x->>'discord' is distinct from p_discord), '[]'::jsonb), actualizado = now() where clave = 'empleados';
  insert into datos (clave, valor, actualizado) values ('log:' || 'b' || to_hex(ms) || (ex->>'id'),
    jsonb_build_object('id', 'b' || to_hex(ms) || (ex->>'id'), 'ts', ms, 'who', coalesce(nullif(p_por,''), 'Dirección'), 'cat', 'Personal', 'lines', jsonb_build_array('Despido desde Discord: ' || (ex->>'name') || ' (' || (ex->>'puesto') || ')')), now());
  return jsonb_build_object('estaba', true, 'id', ex->>'id', 'nombre', ex->>'name', 'puesto', ex->>'puesto');
end $function$

CREATE OR REPLACE FUNCTION public.hg_baja_por_id(p_id text, p_por text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
