    jsonb_build_object('id', 'b' || to_hex(ms) || p_id, 'ts', ms, 'who', coalesce(nullif(p_por,''), 'Dirección'), 'cat', 'Personal',
      'lines', jsonb_build_array('Despido desde Discord: ' || (ex->>'name') || ' (' || (ex->>'puesto') || ')')), now());
