end $function$

CREATE OR REPLACE FUNCTION public.hg_duelo_disparo(p_id text, p_user text, p_ahora bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d bot_duelos; begin
  select * into d from bot_duelos where id=p_id for update;
  if d is null then return jsonb_build_object('error','NO'); end if;
  if p_user not in (d.retador, d.rival) then return jsonb_build_object('error','AJENO'); end if;
  if d.estado <> 'armado' and d.estado <> 'fuego' then return jsonb_build_object('error','ESTADO','estado',d.estado,'ganador',d.ganador); end if;
  if d.fuego is null or p_ahora < d.fuego then
    update bot_duelos set estado='fin', ganador=case when p_user=d.retador then d.rival else d.retador end, ms=null where id=p_id;
    return jsonb_build_object('pronto',true,'ganador',case when p_user=d.retador then d.rival else d.retador end);
  end if;
  update bot_duelos set estado='fin', ganador=p_user, ms=(p_ahora-d.fuego)::int where id=p_id;
  return jsonb_build_object('ganador',p_user,'ms',p_ahora-d.fuego);
end $function$

CREATE OR REPLACE FUNCTION public.hg_ms(t text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if t is null or t = '' then return 0; end if;
  if t ~ '^[0-9]+$' then return t::bigint; end if;
  return (extract(epoch from t::timestamptz) * 1000)::bigint;
exception when others then
  return 0;
end $function$

CREATE OR REPLACE FUNCTION public.hg_pendientes_empleado(p_emp text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  prod   text;
  lot    record;
  s      record;
  ids    text[];
  emps   text[];
  ts     bigint[];
  q      integer[];
  vend   integer[];
  i      integer;
  n      integer;
  rest   integer;
  f      integer;
  total  integer := 0;
begin
  for prod in
    select distinct valor->>'prod' from datos
    where clave like 'fablote:%' and valor->>'empId' = p_emp and valor->>'prod' is not null
  loop
    ids := '{}'; emps := '{}'; ts := '{}'; q := '{}'; vend := '{}';
    for lot in
      select l.clave, l.valor->>'empId' as emp, hg_ms(l.valor->>'ts') as t, coalesce((l.valor->>'q')::integer, 0) as cant
      from datos l
      where l.clave like 'fablote:%' and l.valor->>'prod' = prod
        and not exists (select 1 from datos a where a.clave like 'fablote:%' and a.valor->>'anula' = substr(l.clave, 9))
      order by hg_ms(l.valor->>'ts'), l.clave
    loop
      ids := ids || lot.clave; emps := emps || lot.emp; ts := ts || lot.t; q := q || lot.cant; vend := vend || 0;
    end loop;
    n := coalesce(array_length(ids, 1), 0);
    for s in
      select hg_ms(d.valor->>'ts') as t, coalesce((it->>'qty')::integer, 0) as cant
      from datos d, jsonb_array_elements(coalesce(d.valor->'items', '[]'::jsonb)) it
      where d.clave like 'venta:%'
        and coalesce((d.valor->>'voided')::boolean, false) = false
        and coalesce((d.valor->>'deleted')::boolean, false) = false
        and coalesce(d.valor->>'op', '') <> 'encargo'
        and it->>'name' = prod
      order by 1
    loop
      rest := s.cant;
      i := 1;
      while rest > 0 and i <= n loop
        exit when ts[i] > s.t;
        f := least(rest, q[i] - vend[i]);
        if f > 0 then vend[i] := vend[i] + f; rest := rest - f; end if;
        i := i + 1;
      end loop;
    end loop;
    for i in 1..n loop
      if emps[i] = p_emp then total := total + greatest(0, q[i] - vend[i]); end if;
    end loop;
  end loop;
  return total;
end $function$

